import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 51 · everyday recipe: marinated flank steak (Google Trends 3/11: flank steak rising in dinner recipes)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, in nineteen sixty-four, a flank steak cost forty-nine cents a pound, because nobody knew what to do with it. It's a long, flat, lean cut from the belly of the cow, with the grain running right down it like the lines on a corduroy coat. Cook it wrong, and it's like chewing a rubber boot. Cook it right, and it's as tender as a filet, for a third of the price.""",
   "sliced flank steak cutting board", "LIKE A RUBBER BOOT")
sc("""So tonight I'm giving you my marinated flank steak, a whole family supper for about fifteen dollars, every step, and the five mistakes that make it tough and chewy. And stay with me, because the last mistake happens on the cutting board, and it's the one that matters most. You can do everything else right and still ruin it in ten seconds.""",
   "tough chewy steak slice", "TEN SECONDS")

ch("London broil")
sc("""When I was a young wife, the magazines called it London broil. There's nothing English about it, honey. It was just a fancy name the butchers used to sell the cheap flank steak. They'd marinate it, broil it hot and fast, and slice it thin. And every young wife in America made it on Saturday night, because it looked like a fancy restaurant dinner.""",
   "1960s magazine London broil ad", "NOTHING ENGLISH ABOUT IT")
sc("""The first time I made it, I broiled it for twenty minutes, until it was gray all the way through, and sliced it thick, the wrong way. My husband chewed one bite for so long, I thought he'd fallen asleep. He was too polite to say anything. The next morning, I asked the butcher, Mr. Albrecht, what I'd done wrong. He laughed for a full minute, then he told me.""",
   "1960s butcher shop counter", "HE LAUGHED FOR A MINUTE")
sc("""Mr. Albrecht's rules were simple. Marinate it, cook it hot and fast, rest it, and slice it thin against the grain. In a minute I'll show you all of them. And today, flank steak is one of the most popular cuts in America for tacos, fajitas, salads and sandwiches. It's not forty-nine cents anymore, but it still feeds a family for less than steak night.""",
   "flank steak tacos fajitas", "MR. ALBRECHT'S RULES")

ch("What you need")
sc("""Here's what you need, honey. One flank steak, about one and a half to two pounds. That feeds four to six people. For the marinade, a quarter cup of soy sauce. A quarter cup of olive oil. Two tablespoons of lemon juice or red wine vinegar. Two tablespoons of brown sugar. Three cloves of garlic, crushed. One teaspoon of black pepper. And a tablespoon of Worcestershire sauce.""",
   "flank steak marinade ingredients", "THE INGREDIENTS")
sc("""And when you buy it, look for a steak that's an even thickness, about an inch, from one end to the other, with bright red meat and only a little fat. If one end is much thinner, it'll overcook while the thick end is still raw. You can fold the thin end under, or pound the thick end a little with a heavy pan, to make it even.""",
   "flank steak package butcher", "AN EVEN THICKNESS")

ch("The marinade")
sc("""Step one. Score the steak. With a sharp knife, make shallow cuts across the top, about an eighth of an inch deep, in a diamond pattern, on both sides. That lets the marinade soak in, and it stops the steak from curling up in the pan. Mr. Albrecht did this for me the first time. Then I learned to do it myself.""",
   "scoring flank steak diamond", "SCORE IT")
sc("""Whisk the marinade together in a bowl. Put the steak in a big zipper bag or a shallow dish, pour the marinade over it, and turn it to coat. Squeeze out the air, close the bag, and put it in the icebox. Mistake number one is skipping the marinade. Flank steak is lean, with very little fat, and the marinade gives it flavor and helps make it tender.""",
   "steak marinating zipper bag", "DON'T SKIP IT")
sc("""How long? At least two hours, and up to overnight. But here's mistake number two. Marinating it too long, two or three days. The acid in the lemon or vinegar starts to break down the outside of the meat, and it turns mushy and gray. Overnight is plenty. I put mine in the bag after breakfast, and it's perfect for supper.""",
   "steak in refrigerator overnight", "OVERNIGHT IS PLENTY")

ch("Hot and fast")
sc("""Step two. Take the steak out of the icebox thirty minutes before cooking. Take it out of the marinade and pat it very dry with paper towels. Mistake number three is putting a wet steak in the pan. A wet steak steams and turns gray. A dry steak sears and gets a dark, delicious brown crust. Throw away the used marinade.""",
   "patting steak dry paper towel", "PAT IT DRY")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now heat a big cast iron skillet over high heat for five minutes, until it's smoking a little. Or heat your grill as hot as it goes, or your broiler with the rack close to the top. Flank steak wants heat, and lots of it. Add a spoon of oil to the skillet.""",
   "cast iron skillet smoking hot", "LOTS OF HEAT")
sc("""Lay the steak in the pan, away from you, and don't touch it. Let it sear for four or five minutes, until it has a deep brown crust. Then flip it once, and cook it another four or five minutes. That's it. Mistake number four is cooking it too long. Flank steak is best medium-rare, pink in the middle. Cook it well done, and no amount of slicing will save it.""",
   "searing flank steak skillet crust", "DON'T TOUCH IT")
sc("""Use a meat thermometer, sweetheart. Take it off the heat at one hundred thirty degrees in the thickest part, for medium-rare, or one thirty-five for medium. It keeps cooking a few degrees as it rests. If somebody in your family wants it well done, give them the thin end, which cooks faster. My brother Danny always got the thin end. He thought it was because he was my favorite.""",
   "meat thermometer in steak", "ONE THIRTY")

sc("""And if you're using the broiler, like we did in the sixties, put the rack so the steak is about three inches from the heat. Line the pan with foil for easy cleaning. Broil it about five minutes a side, and watch it closely, because broilers are all different. Mine sets off the smoke alarm every single time, so I open the kitchen window first. The neighbors know it's steak night.""",
   "steak under oven broiler", "STEAK NIGHT")

ch("Resting")
sc("""Step three. Put the steak on a cutting board, cover it loosely with foil, and let it rest for ten minutes. Don't cut it right away. The juices need time to settle back into the meat. If you cut it hot, all that juice runs out onto the board, and the meat on the plate is dry. Use those ten minutes to set the table.""",
   "steak resting under foil", "REST TEN MINUTES")
sc("""So far, score it, marinate it overnight but not longer, pat it dry, sear it hot and fast, take it off at one thirty, and rest it ten minutes. Now the last mistake I promised you, the one that happens on the cutting board in ten seconds. It's the one Mr. Albrecht laughed about. Slicing it the wrong way.""",
   "cutting board knife steak", "THE CUTTING BOARD")

ch("Against the grain")
sc("""Look at the steak, honey. You'll see long lines running down it, from one end to the other, like the threads in a piece of corduroy. That's the grain, the muscle fibers. Mistake number five is slicing along those lines, with the grain. Then every slice is made of long, stringy fibers, and you chew and chew and chew. That's what my husband was doing for so long.""",
   "flank steak grain lines close up", "LIKE CORDUROY")
sc("""Instead, turn the steak so the lines run left to right in front of you. Then slice across them, against the grain, into thin slices, about a quarter of an inch. Hold your knife at a slant, almost flat, so the slices are wide. Now every slice has only short little fibers, and it's tender as butter. Same steak, sweetheart. Just a different direction.""",
   "slicing steak against grain thin", "ACROSS THE GRAIN")

ch("Serving")
sc("""Lay the slices on a warm platter, fanned out, and pour any juice from the cutting board over them. Sprinkle with a little coarse salt and chopped parsley. I serve it with baked potatoes and a green salad. Or roasted potatoes and green beans. My husband liked a spoon of horseradish sauce on the side, and he never chewed for a full minute again.""",
   "sliced steak platter potatoes salad", "TENDER AS BUTTER")
sc("""And the leftovers, honey, are the best part. Thin slices of cold flank steak on a sandwich with horseradish and onions. Or warm them in a skillet with peppers and onions for fajitas. Or on top of a green salad with blue cheese. My granddaughter makes steak tacos with it every Tuesday, with lime and cilantro. It keeps three days in the icebox.""",
   "steak fajitas peppers onions skillet", "TACO TUESDAY")
sc("""And you can change the marinade any way you like. For a Mexican flavor, use lime juice, cumin, chili powder and garlic. For an Asian flavor, soy sauce, ginger, sesame oil and honey. For an Italian flavor, balsamic vinegar, olive oil, rosemary and garlic. The method stays exactly the same. Marinade, hot and fast, rest, and slice against the grain.""",
   "different marinades bowls", "THE METHOD STAYS THE SAME")

ch("Grandma's kitchen")
sc("""So one more time. Buy an even steak, and score it. Marinate it overnight, not longer. Take it out early and pat it dry. Sear it hot and fast, four or five minutes a side. Take it off at one thirty. Rest it ten minutes. And slice it thin, against the grain. That's how Mr. Albrecht taught me, and it's never been tough since.""",
   "flank steak dinner family table", "NEVER TOUGH")
sc("""Tell me in the comments, sweetheart. Did your family call it London broil? And what's your favorite way to eat it? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "warm kitchen evening supper", "LONDON BROIL?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma51", "Flank Steak EVERYONE Cooks WRONG (Why Yours Is TOUGH and CHEWY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "London broil, a mid-century American name for marinated, broiled flank steak sliced against the grain.",
      "Recipe as written by Grandma Ruth: 1 1/2 to 2 lb flank steak; marinade of 1/4 cup soy sauce, 1/4 cup olive oil, 2 tbsp lemon juice or vinegar, 2 tbsp brown sugar, 3 garlic cloves, 1 tsp pepper, 1 tbsp Worcestershire; 2 hours to overnight; seared 4 to 5 minutes per side to 130 F; rested 10 minutes."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
